export interface TileRect {
	x: number;
	y: number;
	width: number;
	height: number;
}

/** The format page images are requested in (set once from StartupInfo). */
let imageFormat: ImageFormat = 'png';

export function setImageFormat(format: ImageFormat) {
	imageFormat = format;
}

/** The most annotations a page image can be asked to leave out (mirrors `MAX_HIDDEN` in
 * `protocol.rs`); with more, the page is asked for with all of them. */
export const MAX_HIDDEN = 1024;

/**
 * URL of a rendered page image. WebView2 (Windows) serves custom protocols as
 * http://<scheme>.localhost; other platforms use <scheme>://localhost. `hidden` names the
 * annotations to leave out, by object number: the ones the annotation list filters out.
 */
export function pageUrl(
	docId: number,
	pageIndex: number,
	scale: number,
	rev: number,
	tile?: TileRect,
	format: ImageFormat = imageFormat,
	hidden: readonly number[] = []
): string {
	const base = isWindows() ? 'http://lectrix.localhost' : 'lectrix://localhost';
	let url = `${base}/page/${docId}/${pageIndex}?scale=${scale.toFixed(3)}&rev=${rev}`;
	if (tile) url += `&tile=${tile.x},${tile.y},${tile.width},${tile.height}`;
	if (hidden.length > 0 && hidden.length <= MAX_HIDDEN) url += `&hide=${hidden.join(',')}`;
	if (format === 'png') url += '&fmt=png';
	return url;
}

/**
 * URL of a preview of a recent file's first page, `width` device pixels wide. `openedAt`
 * is the entry's, so the URL fails rather than shows another file once the list changes.
 */
export function recentPreviewUrl(index: number, openedAt: number, width: number): string {
	const base = isWindows() ? 'http://lectrix.localhost' : 'lectrix://localhost';
	return `${base}/recent/${index}?w=${Math.round(width)}&opened=${openedAt}`;
}

function isWindows(): boolean {
	return typeof navigator !== 'undefined' && /Windows/i.test(navigator.userAgent);
}

/** A fetched page image, ready to draw once into a canvas. */
export interface PageImage {
	width: number;
	height: number;
	/** Draws the image at the canvas origin, once; then its pixels are released. */
	draw(ctx: CanvasRenderingContext2D): void;
}

/** Fetches a page or tile (raw RGBA or PNG, by the response type). */
export async function fetchPageImage(url: string, signal?: AbortSignal): Promise<PageImage> {
	const response = await fetch(url, { signal });
	if (!response.ok) throw new Error(`${response.status} ${await response.text()}`);
	if (response.headers.get('Content-Type') === 'image/png') {
		let bitmap: ImageBitmap | null = await createImageBitmap(await response.blob());
		const { width, height } = bitmap;
		return {
			width,
			height,
			draw: (ctx) => {
				if (!bitmap) return;
				ctx.drawImage(bitmap, 0, 0);
				bitmap.close();
				bitmap = null;
			}
		};
	}
	const width = Number(response.headers.get('X-Lectrix-Width'));
	const height = Number(response.headers.get('X-Lectrix-Height'));
	const buffer = await response.arrayBuffer();
	if (!width || !height || buffer.byteLength !== width * height * 4) {
		throw new Error(`unexpected image size ${width}x${height} (${buffer.byteLength} bytes)`);
	}
	// Dropped after drawing: the request's promise outlives the draw, and must not keep
	// megabytes of pixels alive next to the canvas that already holds them.
	let pixels: ImageData | null = new ImageData(new Uint8ClampedArray(buffer), width, height);
	return {
		width,
		height,
		draw: (ctx) => {
			if (pixels) ctx.putImageData(pixels, 0, 0);
			pixels = null;
		}
	};
}

/**
 * Has Rust render the page image at `url` and keep it, without sending it (`warm=1`): a
 * page rendered ahead, which is then there when it is shown.
 */
export async function warmPageImage(url: string): Promise<void> {
	const response = await fetch(`${url}&warm=1`);
	if (!response.ok) throw new Error(`${response.status} ${await response.text()}`);
}
